import React from 'react';
import { FormItem, FormButtonGroup, Submit, Upload, FormLayout } from '@storage-fe/formily-arco';
import { createForm } from '@formily/core';
import { FormProvider, Field } from '@formily/react';

const form = createForm();

export default () => (
  <FormProvider form={form}>
    <FormLayout labelCol={6} wrapperCol={10}>
      <Field name="upload" title="上传" required decorator={[FormItem]} component={[Upload]} />
      <Field
        name="upload2"
        title="卡片上传"
        required
        decorator={[FormItem]}
        component={[
          Upload,
          {
            listType: 'picture-card',
            multiple: true,
          },
        ]}
      />
      <Field
        name="upload3"
        title="拖拽上传"
        required
        decorator={[FormItem]}
        component={[
          Upload,
          {
            multiple: true,
            drag: true,
          },
        ]}
      />
      <FormButtonGroup.FormItem>
        <Submit onSubmit={console.log}>提交</Submit>
      </FormButtonGroup.FormItem>
    </FormLayout>
  </FormProvider>
);
